//! 🎵️ Handcrafted ID3 tag and MPEG frame entities with ordered intrinsic octets.
use super::*;
use std::collections::BTreeMap;
use semio_framework_os_kernel::{sqlite_snapshot::{artifact::{Cell,Projection,NativeEncodingBound,reconstruct_text},validate_sqlite_database_schema,SnapshotEncoding,SqliteDatabase,SqliteRow,SqliteSnapshotControl,SqliteSnapshotPhase},ArtifactSqliteSnapshot};

type Entities<'a>=BTreeMap<i64,&'a SqliteRow>;
fn checkpoint(control:&mut SqliteSnapshotControl<'_>,position:usize,total:usize)->Result<(),String>{if position%256==0{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,position,total)?;}Ok(())}
fn octet(row:&SqliteRow,column:usize)->Result<u8,String>{u8::try_from(row.integer(column)?).map_err(|error|error.to_string())}
fn short(row:&SqliteRow,column:usize)->Result<u16,String>{u16::try_from(row.integer(column)?).map_err(|error|error.to_string())}
fn flag(row:&SqliteRow,column:usize)->Result<bool,String>{match row.integer(column)?{0=>Ok(false),1=>Ok(true),_=>Err("MP3 header flag must be boolean".into())}}
fn entities<'a>(database:&'a SqliteDatabase,table:&str,columns:usize,control:&mut SqliteSnapshotControl<'_>)->Result<Entities<'a>,String>{let rows=&database.table(table)?.rows;let mut entities=BTreeMap::new();for(position,row)in rows.iter().enumerate(){checkpoint(control,position,rows.len())?;if row.values.len()!=columns||row.rowid<=0||row.integer(0)?!=row.rowid||entities.insert(row.rowid,row).is_some(){return Err(format!("{table} requires unique positive aliased identities and exact columns"));}}Ok(entities)}
fn optional_tag<'a>(database:&'a SqliteDatabase,table:&str,columns:usize,control:&mut SqliteSnapshotControl<'_>)->Result<Entities<'a>,String>{let rows=entities(database,table,columns,control)?;if rows.len()>1||rows.keys().any(|&id|id!=1){return Err("MP3 optional tag must have the document identity".into());}Ok(rows)}
fn groups<'a>(rows:&Entities<'a>,parents:&Entities<'_>,control:&mut SqliteSnapshotControl<'_>)->Result<BTreeMap<i64,Vec<&'a SqliteRow>>,String>{
 let mut groups=BTreeMap::<i64,Vec<&SqliteRow>>::new();for(position,&row)in rows.values().enumerate(){checkpoint(control,position,rows.len())?;let owner=row.integer(1)?;if !parents.contains_key(&owner){return Err("MP3 ordered entity has an unknown owner".into());}groups.entry(owner).or_default().push(row);}
 for(group,rows)in groups.values_mut().enumerate(){checkpoint(control,group,0)?;let mut slots=vec![None;rows.len()];for(position,&row)in rows.iter().enumerate(){checkpoint(control,position,rows.len())?;let ordinal=usize::try_from(row.integer(2)?).map_err(|error|error.to_string())?;if slots.get_mut(ordinal).ok_or("MP3 ordinals must be dense")?.replace(row).is_some(){return Err("MP3 ordinals must be unique".into());}}let mut ordered=Vec::new();for(position,row)in slots.into_iter().enumerate(){checkpoint(control,position,rows.len())?;ordered.push(row.ok_or("MP3 ordinals must be dense")?);}*rows=ordered;}Ok(groups)
}
fn write_octets(out:&mut Projection<'_,'_>,table:&str,owner:i64,bytes:&[u8])->Result<(),String>{for(ordinal,byte)in bytes.iter().enumerate(){out.insert(table,&[Cell::Integer(owner),Cell::Integer(i64::try_from(ordinal).map_err(|error|error.to_string())?),Cell::Integer((*byte).into())])?;}Ok(())}
fn read_octets(rows:Option<&Vec<&SqliteRow>>,control:&mut SqliteSnapshotControl<'_>)->Result<Vec<u8>,String>{let mut bytes=Vec::new();for row in rows.into_iter().flatten(){checkpoint(control,bytes.len(),0)?;bytes.push(octet(row,3)?);}Ok(bytes)}
fn header(row:&SqliteRow)->Result<Mp3FrameHeader,String>{Ok(Mp3FrameHeader{mpeg_version_id:octet(row,3)?,layer:octet(row,4)?,protection_bit:flag(row,5)?,bitrate_index:octet(row,6)?,sample_rate_index:octet(row,7)?,padding:flag(row,8)?,private_bit:flag(row,9)?,channel_mode:octet(row,10)?,mode_extension:octet(row,11)?,copyright:flag(row,12)?,original:flag(row,13)?,emphasis:octet(row,14)?})}

impl ArtifactSqliteSnapshot for Mp3Snapshot{
 const SQLITE_SCHEMA:&'static str=include_str!("🗄️.sql");
 fn preflight_sqlite_snapshot_encoding(&self,_encoding:SnapshotEncoding,control:&mut SqliteSnapshotControl<'_>)->Result<(),String>{let mut bound=NativeEncodingBound::new(control)?;bound.add(16384)?;bound.repeated(self.schema.len(),24)?;if let Some(tag)=&self.id3v2{bound.add(2048)?;for frame in &tag.frames{bound.add(1024)?;bound.repeated(frame.id.len(),24)?;bound.repeated(frame.data.len(),16)?;}}if let Some(tag)=&self.id3v1{bound.add(512)?;bound.repeated(tag.raw.len(),16)?;}for frame in &self.frames{bound.add(4096)?;bound.repeated(frame.payload.len(),16)?;}bound.finish()}
 fn to_sqlite_database(&self,control:&mut SqliteSnapshotControl<'_>)->Result<SqliteDatabase,String>{
  let mut out=Projection::new(Self::SQLITE_SCHEMA,control)?;out.insert("mp3_document",&[Cell::Text(&self.schema)])?;
  if let Some(tag)=&self.id3v2{out.insert_key("mp3_id3v2_tag",1,&[Cell::Integer(tag.major_version.into()),Cell::Integer(tag.minor_version.into()),Cell::Integer(tag.flags.into())])?;for(ordinal,frame)in tag.frames.iter().enumerate(){let id=out.insert("mp3_id3v2_frame",&[Cell::Integer(1),Cell::Integer(i64::try_from(ordinal).map_err(|error|error.to_string())?),Cell::Text(&frame.id),Cell::Integer(frame.flags.into())])?;write_octets(&mut out,"mp3_id3v2_frame_octet",id,&frame.data)?;}}
  if let Some(tag)=&self.id3v1{out.insert_key("mp3_id3v1_tag",1,&[])?;write_octets(&mut out,"mp3_id3v1_octet",1,&tag.raw)?;}
  for(ordinal,frame)in self.frames.iter().enumerate(){let h=&frame.header;let id=out.insert("mp3_audio_frame",&[Cell::Integer(1),Cell::Integer(i64::try_from(ordinal).map_err(|error|error.to_string())?),Cell::Integer(h.mpeg_version_id.into()),Cell::Integer(h.layer.into()),Cell::Integer(i64::from(h.protection_bit)),Cell::Integer(h.bitrate_index.into()),Cell::Integer(h.sample_rate_index.into()),Cell::Integer(i64::from(h.padding)),Cell::Integer(i64::from(h.private_bit)),Cell::Integer(h.channel_mode.into()),Cell::Integer(h.mode_extension.into()),Cell::Integer(i64::from(h.copyright)),Cell::Integer(i64::from(h.original)),Cell::Integer(h.emphasis.into())])?;write_octets(&mut out,"mp3_audio_payload_octet",id,&frame.payload)?;}out.finish()
 }
 fn from_sqlite_database(database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>)->Result<Self,String>{
  validate_sqlite_database_schema(database,Self::SQLITE_SCHEMA,control.limits()).map_err(|error|error.to_string())?;control.check_database(database,SqliteSnapshotPhase::ReconstructSnapshot)?;let documents=entities(database,"mp3_document",2,control)?;if documents.len()!=1||!documents.contains_key(&1){return Err("MP3 requires document identity one".into());}let tags=optional_tag(database,"mp3_id3v2_tag",4,control)?;let trailers=optional_tag(database,"mp3_id3v1_tag",1,control)?;
  let id3_frames=entities(database,"mp3_id3v2_frame",5,control)?;let ordered_tags=groups(&id3_frames,&tags,control)?;let tag_octets=groups(&entities(database,"mp3_id3v2_frame_octet",4,control)?,&id3_frames,control)?;let trailer_octets=groups(&entities(database,"mp3_id3v1_octet",4,control)?,&trailers,control)?;
  let id3v2=if let Some(tag)=tags.get(&1){let mut frames=Vec::new();for row in ordered_tags.get(&1).into_iter().flatten(){checkpoint(control,frames.len(),0)?;frames.push(Id3Frame{id:reconstruct_text(control,row.text(3)?)?,flags:short(row,4)?,data:read_octets(tag_octets.get(&row.rowid),control)?});}Some(Id3v2Tag{major_version:octet(tag,1)?,minor_version:octet(tag,2)?,flags:octet(tag,3)?,frames})}else{None};let id3v1=if trailers.is_empty(){None}else{Some(Id3v1Tag{raw:read_octets(trailer_octets.get(&1),control)?})};
  let audio=entities(database,"mp3_audio_frame",15,control)?;let ordered_audio=groups(&audio,&documents,control)?;let audio_octets=groups(&entities(database,"mp3_audio_payload_octet",4,control)?,&audio,control)?;let mut frames=Vec::new();for row in ordered_audio.get(&1).into_iter().flatten(){checkpoint(control,frames.len(),0)?;frames.push(Mp3Frame{header:header(row)?,payload:read_octets(audio_octets.get(&row.rowid),control)?});}let result=Self{schema:reconstruct_text(control,documents[&1].text(1)?)?,id3v2,frames,id3v1};control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,1,1)?;Ok(result)
 }
}
